window.renderOAIcon = function(name, size = 16, className = '') {
  const inner = window.OA_ICONS_MAP[name] || window.OA_ICONS_MAP[(name || '').toLowerCase()] || '';
  if (!inner) return '';
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" color="currentColor" class="' + className + '" stroke-width="1.5" stroke="currentColor">' + inner + '</svg>';
};
